def to_lmstudio(apps, schema_editor):
    """Bisherige LM-Studio-Anbieter (OpenAI-kompatibel, lokal) auf die neue
    Schnittstelle: mit Modellverwaltung oder lokal auf Port 1234."""
    Provider = apps.get_model("chat", "Provider")
    for provider in Provider.objects.filter(kind="openai_compat"):
        if provider.manage_models or (provider.is_local and ":1234" in provider.base_url):
            provider.kind = "lmstudio"
            provider.is_local = True
            # Eine Angabe: Server-Wurzel (Chat /v1 und Verwaltung /api/v1 abgeleitet).
            provider.base_url = provider.base_url.rstrip("/").removesuffix("/v1")
            provider.save(update_fields=["kind", "is_local", "base_url"])


